check "PriorityClass ads-critical: 100000, not global default" bash -c "[ \"\$(kubectl --context main get priorityclass ads-critical -o jsonpath='{.value}/{.globalDefault}')\" != '' ] && v=\$(kubectl --context main get priorityclass ads-critical -o jsonpath='{.value}/{.globalDefault}') && { [ \"\$v\" = 100000/false ] || [ \"\$v\" = 100000/ ]; }"
check "ad-server uses ads-critical and requests 50m/32Mi" bash -c "[ \"\$(kubectl --context main -n ads get deploy ad-server -o jsonpath='{.spec.template.spec.priorityClassName}|{.spec.template.spec.containers[0].resources.requests.cpu}|{.spec.template.spec.containers[0].resources.requests.memory}')\" = 'ads-critical|50m|32Mi' ]"
check "spread constraint: hostname, maxSkew 1, DoNotSchedule" bash -c "[ \"\$(kubectl --context main -n ads get deploy ad-server -o jsonpath='{.spec.template.spec.topologySpreadConstraints[0].topologyKey}|{.spec.template.spec.topologySpreadConstraints[0].maxSkew}|{.spec.template.spec.topologySpreadConstraints[0].whenUnsatisfiable}')\" = 'kubernetes.io/hostname|1|DoNotSchedule' ]"
check "4 replicas ready, 2 on each worker" bash -c "deploy_ready main ad-server ads 4 &&
  [ \"\$(kubectl --context main -n ads get pods --field-selector=status.phase=Running -o jsonpath='{range .items[*]}{.spec.nodeName}{\"\\n\"}{end}' | sort | uniq -c | awk '{print \$1\":\"\$2}' | tr '\n' ' ')\" = \"2:$MAIN_W1 2:$MAIN_W2 \" ]"
